insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('masai-mara', 'Maasai Mara', 'Maasai Mara', 'Narok County · southwest', 'Narok County · Südwesten', 'Kenya’s most famous reserve and the home of the Maasai. Big cats are seen year-round, and from July to October the Great Migration crosses the Mara River. The surrounding community conservancies keep vehicle numbers low.', 'Kenias berühmtestes Schutzgebiet und Heimat der Maasai. Großkatzen sieht man das ganze Jahr, und von Juli bis Oktober überquert die Große Tierwanderung den Mara River. Die umliegenden Gemeinde-Schutzgebiete halten die Zahl der Fahrzeuge niedrig.', 'All year; July–October for river crossings', 'Ganzjährig; Juli–Oktober für Flussüberquerungen', 'safari mara masai migration big five lion', 'safari', -1.4939, 35.1439, null, 'savannah', true, 1) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('amboseli', 'Amboseli', 'Amboseli', 'Kajiado County · south', 'Kajiado County · Süden', 'Large elephant herds wander the swamps beneath Mount Kilimanjaro, which rises just across the border in Tanzania. Clear mornings give the classic view of the snow-capped peak.', 'Große Elefantenherden ziehen durch die Sümpfe am Fuß des Kilimanjaro, der direkt jenseits der Grenze in Tansania aufragt. An klaren Morgen zeigt sich der schneebedeckte Gipfel.', 'June–October, January–February', 'Juni–Oktober, Januar–Februar', 'safari elephants kilimanjaro', 'safari', -2.6527, 37.2606, null, 'savannah', true, 2) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('tsavo', 'Tsavo East & West', 'Tsavo East & West', 'Between Nairobi and the coast', 'Zwischen Nairobi und der Küste', 'Together one of the largest protected areas in Africa. Tsavo East is known for elephants dusted red by the soil; Tsavo West has volcanic hills and the clear pools of Mzima Springs.', 'Zusammen eines der größten Schutzgebiete Afrikas. Tsavo East ist für seine von der Erde rot gefärbten Elefanten bekannt, Tsavo West für Vulkanhügel und die klaren Quellen von Mzima Springs.', 'June–October', 'Juni–Oktober', 'safari elephants red wilderness mzima', 'safari', -2.9833, 38.4667, null, 'north', false, 3) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('samburu', 'Samburu', 'Samburu', 'Samburu County · north', 'Samburu County · Norden', 'Dry, rugged country along the Ewaso Ng’iro river and home of the Samburu people. Look for the “Samburu Special Five”: Grevy’s zebra, reticulated giraffe, gerenuk, beisa oryx and Somali ostrich.', 'Trockenes, raues Land am Fluss Ewaso Ng’iro und Heimat der Samburu. Hier leben die „Samburu Special Five“: Grevyzebra, Netzgiraffe, Giraffengazelle, Beisa-Oryx und Somali-Strauß.', 'June–October, December–March', 'Juni–Oktober, Dezember–März', 'safari north desert special five', 'safari', 0.6167, 37.5333, null, 'north', false, 4) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('nakuru', 'Lake Nakuru', 'Lake Nakuru', 'Rift Valley', 'Rift Valley', 'A compact park around a Rift Valley lake, and one of the best places in Kenya to see both black and white rhinos. Flamingo numbers rise and fall with the water level.', 'Ein kompakter Park um einen See im Rift Valley und einer der besten Orte Kenias, um Spitz- und Breitmaulnashörner zu sehen. Die Zahl der Flamingos schwankt mit dem Wasserstand.', 'All year', 'Ganzjährig', 'safari rhino flamingo lake', 'lakes', -0.3667, 36.0833, null, 'flamingo', true, 5) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('naivasha', 'Lake Naivasha & Hell’s Gate', 'Lake Naivasha & Hell’s Gate', 'Rift Valley', 'Rift Valley', 'A freshwater lake full of hippos and birdlife, with walking safaris on Crescent Island. Next door, Hell’s Gate is one of the few parks where you can cycle among zebras and walk through a gorge.', 'Ein Süßwassersee voller Flusspferde und Vögel, mit Fußsafaris auf Crescent Island. Gleich nebenan liegt Hell’s Gate, einer der wenigen Parks, in denen man zwischen Zebras Rad fahren und durch eine Schlucht wandern kann.', 'All year', 'Ganzjährig', 'boat hippo cycling walking gorge', 'lakes', -0.7667, 36.4167, null, 'lake', false, 6) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('mount-kenya', 'Mount Kenya & Ol Pejeta', 'Mount Kenya & Ol Pejeta', 'Central highlands · Laikipia', 'Zentrales Hochland · Laikipia', 'Africa’s second-highest mountain at 5,199 m, with forest walks on its lower slopes. On the plains below, Ol Pejeta Conservancy protects rhinos and runs a chimpanzee sanctuary.', 'Mit 5.199 m Afrikas zweithöchster Berg, mit Waldwanderungen an den unteren Hängen. In der Ebene darunter schützt das Ol Pejeta Conservancy Nashörner und betreibt ein Schimpansen-Schutzzentrum.', 'January–February, July–October', 'Januar–Februar, Juli–Oktober', 'mountain hiking rhino chimpanzee', 'lakes', -0.1521, 37.3084, null, 'mountain', false, 7) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('diani', 'Diani Beach', 'Diani Beach', 'South coast', 'Südküste', 'Long white sand on the Indian Ocean south of Mombasa. Snorkel or dive at Kisite-Mpunguti marine park and watch colobus monkeys in the coastal forest.', 'Langer weißer Sandstrand am Indischen Ozean südlich von Mombasa. Schnorcheln oder tauchen Sie im Meeresschutzgebiet Kisite-Mpunguti und beobachten Sie Stummelaffen im Küstenwald.', 'December–March, July–October', 'Dezember–März, Juli–Oktober', 'beach strand sea snorkel coast', 'coast', -4.2797, 39.5947, null, 'coast', true, 8) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('mombasa', 'Mombasa', 'Mombasa', 'Coast', 'Küste', 'Kenya’s old port city. Walk the lanes of Old Town, browse the spice market and visit Fort Jesus, a 16th-century Portuguese fort and UNESCO World Heritage Site.', 'Kenias alte Hafenstadt. Spazieren Sie durch die Gassen der Altstadt, stöbern Sie auf dem Gewürzmarkt und besuchen Sie Fort Jesus, eine portugiesische Festung aus dem 16. Jahrhundert und UNESCO-Welterbe.', 'December–March, July–October', 'Dezember–März, Juli–Oktober', 'beach strand coast city fort swahili', 'coast', -4.0435, 39.6682, null, 'coast', false, 9) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('lamu', 'Lamu', 'Lamu', 'North coast', 'Nordküste', 'An island where donkeys and dhows replace cars. Lamu Old Town is a UNESCO World Heritage Site and one of the oldest Swahili settlements on the coast.', 'Eine Insel, auf der Esel und Dhaus die Autos ersetzen. Die Altstadt von Lamu ist UNESCO-Welterbe und eine der ältesten Swahili-Siedlungen der Küste.', 'November–March', 'November–März', 'beach strand island swahili dhow', 'coast', -2.2717, 40.902, null, 'coast', false, 10) on conflict (slug) do nothing;
insert into public.destinations (slug, name_en, name_de, region_en, region_de, description_en, description_de, best_time_en, best_time_de, keywords, group_key, latitude, longitude, image, placeholder, featured, position) values ('nairobi', 'Nairobi', 'Nairobi', 'Capital', 'Hauptstadt', 'The only capital with a national park inside its limits, where giraffes graze in front of the skyline. Many trips start here, with a visit to an elephant orphanage or the Giraffe Centre.', 'Die einzige Hauptstadt mit einem Nationalpark innerhalb der Stadtgrenzen, wo Giraffen vor der Skyline grasen. Viele Reisen beginnen hier, etwa mit einem Besuch im Elefantenwaisenhaus oder im Giraffe Centre.', 'All year', 'Ganzjährig', 'city stadt giraffe elephant orphanage', 'coast', -1.2921, 36.8219, null, 'city', false, 11) on conflict (slug) do nothing;
insert into public.trips (slug, title_en, title_de, summary_en, summary_de, season_en, season_de, duration_days, price_from, style, status, cover_image, placeholder, featured, position) values ('mara-classic', 'Maasai Mara Classic', 'Maasai Mara Klassik', 'Three nights in the Mara with twice-daily game drives, a Maasai village visit and an optional sunrise balloon flight.', 'Drei Nächte in der Maasai Mara mit zwei Pirschfahrten täglich, Besuch eines Maasai-Dorfes und optionaler Ballonfahrt bei Sonnenaufgang.', 'All year; July–October for river crossings', 'Ganzjährig; Juli–Oktober für Flussüberquerungen', 4, 1290, 'safari', 'published', null, 'savannah', true, 1) on conflict (slug) do nothing;
