insert into public.posts (slug, title_en, title_de, excerpt_en, excerpt_de, body_en, body_de, category_en, category_de, placeholder, status, published_at, meta_title_en, meta_title_de, meta_description_en, meta_description_de) values ('kenya-eta-before-you-fly', 'Kenya’s eTA: what to sort out before you fly', 'Kenias eTA: Was Sie vor dem Abflug erledigen sollten', 'Every visitor applies online before departure. A simple checklist for the application.', 'Alle Reisenden beantragen sie vor der Abreise online. Eine einfache Checkliste für den Antrag.', '<p>Kenya asks most visitors to apply online for an Electronic Travel Authorisation (eTA) before they travel. You can’t get it on arrival, so it belongs on your checklist as soon as your flights are booked.</p><h2>What you need for the application</h2><ul><li>A passport valid for your whole stay, with blank pages</li><li>A recent passport-style photo</li><li>Your flight details and where you’ll stay on the first night</li><li>A payment card for the fee</li></ul><h2>Our tips</h2><ul><li>Apply only on the official government portal. Lookalike sites charge extra fees.</li><li>Fees and processing times can change, so check the portal for the current details and apply well before you fly.</li><li>Keep a copy of the approval on your phone and a printed copy in your hand luggage.</li></ul><p>When you plan a trip with us, we send you the accommodation details you need for the form.</p>', '<p>Kenia verlangt von den meisten Reisenden, vor der Reise online eine elektronische Reisegenehmigung (eTA) zu beantragen. Bei der Ankunft gibt es sie nicht, deshalb gehört sie auf Ihre Liste, sobald die Flüge gebucht sind.</p><h2>Was Sie für den Antrag brauchen</h2><ul><li>Einen Reisepass, der für die gesamte Reise gültig ist und freie Seiten hat</li><li>Ein aktuelles Passfoto</li><li>Ihre Flugdaten und die Unterkunft für die erste Nacht</li><li>Eine Zahlungskarte für die Gebühr</li></ul><h2>Unsere Tipps</h2><ul><li>Beantragen Sie die eTA nur auf dem offiziellen Regierungsportal. Nachahmerseiten verlangen zusätzliche Gebühren.</li><li>Gebühren und Bearbeitungszeiten können sich ändern. Prüfen Sie die aktuellen Angaben auf dem Portal und beantragen Sie rechtzeitig vor dem Abflug.</li><li>Speichern Sie die Genehmigung auf dem Handy und nehmen Sie einen Ausdruck im Handgepäck mit.</li></ul><p>Wenn Sie mit uns planen, schicken wir Ihnen die Angaben zur Unterkunft, die Sie für das Formular brauchen.</p>', 'Entry & visas', 'Einreise', 'city', 'published', '2026-08-28T08:00:00Z', '', '', 'Every visitor applies online before departure. A simple checklist for the application.', 'Alle Reisenden beantragen sie vor der Abreise online. Eine einfache Checkliste für den Antrag.') on conflict (slug) do nothing;
insert into public.post_trips (post_id, trip_id) values ((select id from public.posts where slug = 'kenya-eta-before-you-fly'), (select id from public.trips where slug = 'mara-classic')) on conflict do nothing;
