insert into public.hero_slides (position, is_welcome, eyebrow_en, eyebrow_de, title_en, title_de, text_en, text_de, link_label_en, link_label_de, destination_id, image, placeholder) values (0, true, 'Supa — welcome', 'Supa – willkommen', 'Kenya, planned by someone who calls it home.', 'Kenia, geplant von jemandem, der dort zu Hause ist.', 'Safaris, coast escapes and everything in between, planned personally by our team in Kenya and Germany.', 'Safaris, Auszeiten an der Küste und alles dazwischen, persönlich geplant von unserem Team in Kenia und Deutschland.', 'Offices in Nairobi and Germany · Sister company of Oloning’o Mara Camp', 'Büros in Nairobi und Deutschland · Schwesterunternehmen des Oloning’o Mara Camp', null, null, 'dawn');
insert into public.hero_slides (position, is_welcome, eyebrow_en, eyebrow_de, title_en, title_de, text_en, text_de, link_label_en, link_label_de, destination_id, image, placeholder) values (1, false, 'Mombasa · Swahili coast', 'Mombasa · Swahili Coast', 'Where the old town meets the Indian Ocean.', 'Wo die Altstadt auf den Indischen Ozean trifft.', 'Fort Jesus, spice markets and warm turquoise water.', 'Fort Jesus, Gewürzmärkte und warmes, türkisfarbenes Wasser.', 'Explore Mombasa', 'Mombasa entdecken', (select id from public.destinations where slug = 'mombasa'), null, 'coast');
insert into public.hero_slides (position, is_welcome, eyebrow_en, eyebrow_de, title_en, title_de, text_en, text_de, link_label_en, link_label_de, destination_id, image, placeholder) values (2, false, 'Maasai Mara', 'Maasai Mara', 'Big cats, open plains and the Great Migration.', 'Großkatzen, weite Ebenen und die Große Tierwanderung.', 'Kenya’s most famous reserve and the home of the Maasai. River crossings usually run July to October.', 'Kenias berühmtestes Schutzgebiet und Heimat der Maasai. Flussüberquerungen gibt es meist von Juli bis Oktober.', 'Explore the Maasai Mara', 'Maasai Mara entdecken', (select id from public.destinations where slug = 'masai-mara'), null, 'savannah');
insert into public.hero_slides (position, is_welcome, eyebrow_en, eyebrow_de, title_en, title_de, text_en, text_de, link_label_en, link_label_de, destination_id, image, placeholder) values (3, false, 'Lake Nakuru', 'Lake Nakuru', 'When the water is right, the shore turns pink.', 'Wenn der Wasserstand stimmt, färbt sich das Ufer rosa.', 'Flamingos along the lake, rhinos in the acacia woodland.', 'Flamingos am Seeufer, Nashörner im Akazienwald.', 'Explore Lake Nakuru', 'Lake Nakuru entdecken', (select id from public.destinations where slug = 'nakuru'), null, 'flamingo');
